const fs = require('fs');
const fetch = require('node-fetch');

// Read and parse the CSV file
const csvContent = fs.readFileSync('/data/samples/user_activity_sample.csv', 'utf8');
const lines = csvContent.trim().split('\n');
const headers = lines[0].split(',');

// Convert CSV to JSON objects matching the UserActivity interface
const records = lines.slice(1).map(line => {
  const values = line.split(',');
  return {
    eventId: values[0],
    eventTs: values[1],
    userId: values[2],
    action: values[3],
    durationMs: parseFloat(values[4]) || 0.0 // Default to 0 if null/undefined
  };
});

console.log(`Processing ${records.length} records...`);

// Send each record to the ingestion API
async function loadData() {
  for (const record of records) {
    try {
      const response = await fetch('http://localhost:4000/ingestion/UserActivity', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(record)
      });

      if (!response.ok) {
        console.error(`Failed to ingest record ${record.eventId}:`, response.statusText);
      } else {
        console.log(`Ingested record ${record.eventId}`);
      }
    } catch (error) {
      console.error(`Error ingesting record ${record.eventId}:`, error.message);
    }
  }

  console.log('Data loading complete!');
}

loadData();

